INSERT INTO tower_upgrade_path (id, tower_id, slot, path_name, path_description, icon_name, historical_basis, source_url, rank_count) VALUES
('morgan_aim', '1008b722-563a-44a0-8b31-c9cca93b9927', 1, 'Deliberate Aim', 'Careful rifle shots hit harder.', 'tower_menu_ranged_square', 'Continental riflemen used aimed fire; damage increases are a game abstraction, not a documented drill unique to Morgan.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('morgan_rifle_practice', '1008b722-563a-44a0-8b31-c9cca93b9927', 2, 'Rifle Practice', 'Practice judging distance extends rifle reach.', 'hero_ability_icon_daniel_morgan', 'Rifle accuracy and range distinguished rifle units from smoothbore musket infantry.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('knowlton_fieldcraft', '72788425-7677-418a-a06c-6b3120f94631', 1, 'Fieldcraft', 'Forward firing positions extend the rangers’ reach.', 'hero_ability_icon_francis_marion', 'Rangers and light troops performed reconnaissance and screening; these ranks represent those practices rather than named historical upgrades.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('knowlton_fire_discipline', '72788425-7677-418a-a06c-6b3120f94631', 2, 'Fire Discipline', 'Practiced loading and firing shortens the time between shots.', 'tower_menu_ranged_square', 'The manual of arms and organized firing were central to Continental infantry training.', 'https://www.nps.gov/vafo/learn/historyculture/vonsteuben.htm', 2),
('whitcomb_marksmanship', 'c5cc2d7b-b08c-4ba7-a532-52ba070589a5', 1, 'Woodland Marksmanship', 'Experienced scouts deliver stronger aimed shots.', 'tower_menu_ranged_square', 'Ranger reconnaissance and aimed small-arms fire supply the historical basis; no unique weapon invention is claimed.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('whitcomb_patrols', 'c5cc2d7b-b08c-4ba7-a532-52ba070589a5', 2, 'Scouting Patrols', 'Surveyed firing positions cover more of the road.', 'hero_ability_icon_daniel_morgan', 'Independent ranger companies scouted frontier routes. Increased reach is a gameplay representation of reconnaissance.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('regulars_bayonet', '9c1aa74b-b783-4fc1-b9c3-daeaf5284146', 1, 'Bayonet Drill', 'Practiced thrusts strengthen every soldier’s attack.', 'tower_menu_melee_square', 'Steuben emphasized bayonet training alongside the manual of arms.', 'https://www.nps.gov/vafo/learn/historyculture/vonsteuben.htm', 2),
('regulars_close_order', '9c1aa74b-b783-4fc1-b9c3-daeaf5284146', 2, 'Close Order', 'A disciplined formation withstands more punishment.', 'hero_skill_icon_rally', 'Continental drill standardized formation and maneuver. Damage reduction represents cohesion, not body armor.', 'https://www.nps.gov/vafo/learn/historyculture/vonsteuben.htm', 2),
('light_bayonet_assault', '634b9957-dce1-4b53-8665-1017904ad89d', 1, 'Bayonet Assault', 'Assault drill speeds up close combat.', 'tower_menu_melee_square', 'Continental light infantry used bayonet assaults, including the attack on Stony Point in 1779.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('light_open_order', '634b9957-dce1-4b53-8665-1017904ad89d', 2, 'Open Order', 'Dispersed movement extends rally reach and improves survival.', 'hero_ability_icon_francis_marion', 'Light infantry screened formations and skirmished in dispersed order. Defense is tactical protection, not armor.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('maryland_resolve', '550638ec-0f26-4329-9719-2d3f2e697238', 1, 'Veteran Resolve', 'Experienced soldiers hold the line longer.', 'hero_skill_icon_rally', 'Maryland Continentals served as veteran line infantry. Health is an abstraction of endurance and cohesion.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('maryland_relief', '550638ec-0f26-4329-9719-2d3f2e697238', 2, 'Orderly Relief', 'Organized relief and camp care restore the garrison sooner.', 'tower_menu_supply_hospital', 'Relieving troops and caring for wounded soldiers were period practices; respawn time is a game abstraction.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('mortar_shell_service', 'f614aea2-b5cb-4cd3-a30d-e33a02c27c90', 1, 'Shell Service', 'Prepared explosive shells strike harder over a broader area.', 'tower_menu_artillery_mortar', 'Revolutionary mortars fired hollow explosive shells on a high trajectory. The upgrade abstracts shell preparation and service.', 'https://www.nps.gov/york/learn/historyculture/revolutionary-war-artillery.htm', 2),
('mortar_bombardment', 'f614aea2-b5cb-4cd3-a30d-e33a02c27c90', 2, 'Practiced Bombardment', 'A practiced detachment maintains faster, more unsettling bombardment.', 'tower_menu_special_square', 'Artillery detachments sustained siege bombardments; fire intervals and morale values are gameplay abstractions.', 'https://www.nps.gov/york/learn/historyculture/revolutionary-war-artillery.htm', 2),
('swivel_grape', '01b02f93-d2ff-4754-9072-35a1aa65cd6d', 1, 'Grape Loads', 'Prepared grapeshot loads strengthen every pellet.', 'tower_menu_artillery_swivel', 'Grapeshot was a period antipersonnel projectile. This retains the existing swivel gun and does not introduce later shrapnel shells.', 'https://www.nps.gov/york/learn/historyculture/revolutionary-war-artillery.htm', 2),
('swivel_drill', '01b02f93-d2ff-4754-9072-35a1aa65cd6d', 2, 'Swivel Drill', 'A practiced crew reloads and traverses the light gun faster.', 'tower_menu_special_square', 'Swivel guns were small, pivot-mounted pieces. Crew practice is represented by faster service and traverse.', 'https://www.nps.gov/york/learn/historyculture/revolutionary-war-artillery.htm', 2),
('siege_round_shot', 'fa950e72-3c9c-420a-ab60-b40cb41407cf', 1, 'Round-Shot Service', 'Well-served solid shot deals greater damage and morale shock.', 'tower_menu_artillery_siege', 'Siege cannon fired solid iron shot. These ranks preserve straight, penetrating shot rather than converting it to an explosive shell.', 'https://www.nps.gov/york/learn/historyculture/revolutionary-war-artillery.htm', 2),
('siege_matrosses', 'fa950e72-3c9c-420a-ab60-b40cb41407cf', 2, 'Trained Matrosses', 'Trained gun assistants speed up loading and aiming.', 'tower_menu_special_square', 'Matrosses assisted artillery crews in moving and serving guns; increased rates represent crew training.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('fieldworks_abatis', '01b5f5d5-5472-4dbd-be95-9089af603422', 1, 'Denser Abatis', 'Tangled felled branches slow passing enemies more strongly.', 'tower_menu_special_square', 'Duportail directed the construction of siegeworks at Yorktown.', 'https://www.army.mil/sapper/history.html', 2),
('fieldworks_extent', '01b5f5d5-5472-4dbd-be95-9089af603422', 2, 'Extended Fieldworks', 'Working parties lay broader abatis beds farther from the post.', 'hero_ability_icon_louis_duportail', 'Revolutionary engineers laid out and constructed field fortifications with working parties.', 'https://www.army.mil/sapper/history.html', 2),
('sapper_powder', '44c58827-2c6c-4ec4-a2f2-43473908aee8', 1, 'Powder Mines', 'Prepared powder mines strike harder across a broader blast area.', 'tower_menu_engineer_sapper', 'Period sappers and miners used gunpowder in siege mining. The existing automatic enemy-boundary trigger is a game abstraction, not a claim of electronic or proximity fuzes.', 'https://www.armyupress.army.mil/Portals/7/combat-studies-institute/csi-books/essayons-the-origins-and-history-of-the-us-army-engineer-school.pdf', 2),
('sapper_details', '44c58827-2c6c-4ec4-a2f2-43473908aee8', 2, 'Miner Details', 'Organized working parties prepare replacement charges sooner.', 'tower_menu_special_square', 'Companies of sappers and miners organized technical working parties during the Revolution.', 'https://www.army.mil/sapper/history.html', 2),
('quartermaster_wagons', 'e6a89c04-b291-4f37-8ad2-0196f75c4401', 1, 'Wagon Trains', 'Additional transport brings more supplies at each wave.', 'tower_menu_supply_quartermaster', 'Quartermasters organized transport and military supply during the Revolution. Coins represent delivered resources.', 'https://quartermaster.army.mil/qm_at_a_glance.html', 2),
('quartermaster_rations', 'e6a89c04-b291-4f37-8ad2-0196f75c4401', 2, 'Ration Issue', 'Regular provisions help nearby troops recover.', 'tower_menu_supply_hospital', 'Army provisions supported soldiers’ endurance. Healing is a game abstraction; rations do not instantly cure wounds.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('ordnance_cartridges', 'e6a89c04-b291-4f37-8ad2-0196f75c4402', 1, 'Cartridge Supply', 'Prepared ammunition keeps nearby ranged and artillery towers firing.', 'tower_menu_supply_ordnance', 'Ordnance stores and prepared cartridges supplied Continental firearms. The aura abstracts ammunition delivery.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('ordnance_wagons', 'e6a89c04-b291-4f37-8ad2-0196f75c4402', 2, 'Ammunition Wagons', 'Wagons carry ammunition farther and deliver more supplies.', 'tower_menu_supply_quartermaster', 'Transport connected ordnance stores to field forces; supply income is an abstraction of delivered stores.', 'https://history.army.mil/portals/143/Images/Publications/catalog/60-4-1.pdf', 2),
('hospital_mates', 'e6a89c04-b291-4f37-8ad2-0196f75c4403', 1, 'Surgeon’s Mates', 'Additional medical attendants improve nearby healing.', 'tower_menu_supply_hospital', 'Surgeons and their mates staffed Revolutionary military hospitals. Healing rates are game abstractions, not modern medical effectiveness.', 'https://www.nps.gov/articles/000/-the-main-body-at-the-church-st-paul-s-and-the-revolutionary-war.htm', 2),
('hospital_stations', 'e6a89c04-b291-4f37-8ad2-0196f75c4403', 2, 'Hospital Stations', 'Additional treatment stations extend the hospital’s reach.', 'tower_menu_supply_quartermaster', 'Churches and other suitable buildings served as Revolutionary military hospitals. Increased range represents a wider network of care.', 'https://www.nps.gov/articles/000/-the-main-body-at-the-church-st-paul-s-and-the-revolutionary-war.htm', 2);
